import React, { useCallback, useEffect, useMemo, useState } from 'react';
import type { DailyIncidentReportFilters } from '../../../models/DailyIncidentReport';
import { useFormOptions } from '../../../hooks/useFormOptions';
import { currentYearDateRange, useReportPeriodFilter } from '../../../hooks/useReportPeriodFilter';
import styles from './DailyIncidentReportFiltersBar.module.css';
import {
  LinErpListFilterBar,
  LinReportPeriodSelectorFields,
  SearchTextInput,
  Select,
  SelectOption,
} from '@linm-soft-org/linm-web-common-components';

const TEST_ID_PREFIX = 'daily-incident-report-list';

interface Props {
  filters: DailyIncidentReportFilters;
  onChange: (f: DailyIncidentReportFilters) => void;
  onClear: () => void;
  loading?: boolean;
}

export const DailyIncidentReportFiltersBar: React.FC<Props> = ({
  filters,
  onChange,
  onClear,
  loading = false,
}) => {
  const [draft, setDraft] = useState<DailyIncidentReportFilters>(filters);
  const { departmentOptions } = useFormOptions('incident-list');

  useEffect(() => {
    setDraft(filters);
  }, [filters]);

  const commitDates = useCallback(
    (fromDate: string, toDate: string) => {
      setDraft((prev) => {
        const next = { ...prev, fromDate, toDate };
        onChange({
          ...next,
          departmentId: next.departmentId || undefined,
        });
        return next;
      });
    },
    [onChange],
  );

  const period = useReportPeriodFilter(commitDates, 'year');

  const allDeptOptions: SelectOption[] = useMemo(
    () => [{ value: '', label: 'Tất cả khoa, phòng' }, ...departmentOptions],
    [departmentOptions],
  );

  const hasActiveFilters = !!(draft.search || draft.departmentId || period.viewMode !== 'year');

  const handleSearch = () => {
    onChange({
      ...draft,
      search: draft.search?.trim() || undefined,
      fromDate: period.fromDate || draft.fromDate,
      toDate: period.toDate || draft.toDate,
      departmentId: draft.departmentId || undefined,
    });
  };

  const handleClear = () => {
    period.resetToDefaultYear();
    const year = currentYearDateRange();
    const next: DailyIncidentReportFilters = {
      fromDate: year.dateFrom,
      toDate: year.dateTo,
    };
    setDraft(next);
    onClear();
  };

  return (
    <LinErpListFilterBar
      testIdPrefix={TEST_ID_PREFIX}
      fromDate={period.fromDate}
      toDate={period.toDate}
      onDateChange={period.handleDateRangeChange}
      onSearch={handleSearch}
      loading={loading}
      leading={(
        <>
          <div data-testid={`${TEST_ID_PREFIX}-field-search`}>
            <SearchTextInput
              label="Tìm kiếm"
              placeholder="Tìm theo mã, khoa/phòng..."
              value={draft.search ?? ''}
              onChange={(search) => setDraft((prev) => ({ ...prev, search }))}
              testId={`${TEST_ID_PREFIX}-search-text`}
            />
          </div>
          <div data-testid={`${TEST_ID_PREFIX}-field-department`}>
            <Select
              label="Khoa, phòng"
              options={allDeptOptions}
              value={draft.departmentId ?? ''}
              onChange={(e) =>
                setDraft((prev) => ({
                  ...prev,
                  departmentId: e.target.value || undefined,
                }))
              }
              size="small"
            />
          </div>
          {hasActiveFilters && (
            <div data-testid={`${TEST_ID_PREFIX}-field-clear`}>
              <button
                className={styles.clearFiltersButton}
                onClick={handleClear}
                type="button"
                title="Xóa bộ lọc"
              >
                <i className="fas fa-times-circle" />
                <span>Xóa bộ lọc</span>
              </button>
            </div>
          )}
        </>
      )}
      dateLeading={(
        <LinReportPeriodSelectorFields
          testIdPrefix={TEST_ID_PREFIX}
          labels={period.periodLabels}
          viewMode={period.viewMode}
          month={period.month}
          year={period.year}
          quarter={period.quarter}
          yearOptions={period.yearOptions}
          onViewModeChange={period.handleViewModeChange}
          onMonthChange={period.setMonth}
          onYearChange={period.setYear}
          onQuarterChange={period.setQuarter}
        />
      )}
    />
  );
};
