import React from 'react';
import type { DailyIncidentReportStats } from '../../../models/DailyIncidentReport';
import { StatsCardsGrid, StatsCard } from '@linm-soft-org/linm-web-common-components';

interface Props {
  stats:         DailyIncidentReportStats;
  loading?:      boolean;
  activeFilter?: 'all' | 'with' | 'without';
  onFilter?:     (key: 'all' | 'with' | 'without') => void;
}

export const DailyIncidentStatsCards: React.FC<Props> = ({
  stats,
  loading,
  activeFilter = 'all',
  onFilter,
}) => {
  const handleClick = (key: 'all' | 'with' | 'without') => {
    if (!onFilter) return;
    onFilter(activeFilter === key ? 'all' : key);
  };

  return (
    <StatsCardsGrid>
      <StatsCard
        label="Tổng báo cáo"
        value={stats.total}
        icon="fas fa-clipboard-list"
        variant="primary"
        loading={loading}
        active={activeFilter === 'all'}
        onClick={() => handleClick('all')}
      />
      <StatsCard
        label="Có sự cố"
        value={stats.withIncident}
        icon="fas fa-exclamation-triangle"
        variant="warning"
        loading={loading}
        active={activeFilter === 'with'}
        onClick={() => handleClick('with')}
      />
      <StatsCard
        label="Không có sự cố"
        value={stats.withoutIncident}
        icon="fas fa-check-circle"
        variant="success"
        loading={loading}
        active={activeFilter === 'without'}
        onClick={() => handleClick('without')}
      />
    </StatsCardsGrid>
  );
};
